CREATE VIEW [DBO].[CUSTDEFAULTROLELOCATION] AS SELECT T1.ACCOUNTNUM AS ACCOUNTNUM, T1.DATAAREAID AS DATAAREAID, T1.PARTITION AS PARTITION, T1.RECID AS RECID, T2.PARTYLOCATION AS PARTYLOCATION, T2.PARTITION AS PARTITION#2, T3.TYPE AS TYPE, T3.PARTITION AS PARTITION#3, T4.PARTY AS PARTY, T4.PARTITION AS PARTITION#4, T5.RECID AS LOGISTICSLOCATION, T5.PARTITION AS PARTITION#5 FROM CUSTDEFAULTLOCATION T1 CROSS JOIN DIRPARTYLOCATIONROLE T2 CROSS JOIN LOGISTICSLOCATIONROLE T3 CROSS JOIN DIRPARTYLOCATION T4 CROSS JOIN LOGISTICSLOCATION T5 WHERE((((( T1.PARTYLOCATIONROLE  =  T2.RECID)  AND ( T1.PARTITION  =  T2.PARTITION))  AND (( T2.LOCATIONROLE  =  T3.RECID)  AND ( T2.PARTITION  =  T3.PARTITION)))  AND (( T2.PARTYLOCATION  =  T4.RECID)  AND ( T2.PARTITION  =  T4.PARTITION)))  AND (( T4.LOCATION  =  T5.RECID)  AND ( T4.PARTITION  =  T5.PARTITION)))